  const MONTHS_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  function getLocalTodayIso() {
    try {
      const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Australia/Melbourne',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }).formatToParts(new Date());
      const y = parts.find((p) => p.type === 'year')?.value;
      const m = parts.find((p) => p.type === 'month')?.value;
      const d = parts.find((p) => p.type === 'day')?.value;
      if (y && m && d) return `${y}-${m}-${d}`;
    } catch (_) {
      // Fallback to local system date
    }
    const now = new Date();
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  }

  function formatIsoDateDisplay(isoStr) {
    if (!isoStr || typeof isoStr !== 'string') return '';
    const match = isoStr.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) return isoStr;
    const year = Number(match[1]);
    const monthIdx = Number(match[2]) - 1;
    const day = Number(match[3]);
    const monthName = MONTHS_SHORT[monthIdx] || match[2];
    return `${day} ${monthName} ${year}`;
  }

  function normalizeVenueName(rawVenue) {
    const str = String(rawVenue || '').trim();
    if (!str || /^calder\s*park(\s*\/\s*track|\s*raceway)?$/i.test(str)) {
      return 'Calder Park Raceway';
    }
    if (/^sandown(\s*international)?(\s*motor)?(\s*raceway)?$/i.test(str)) {
      return 'Sandown Raceway';
    }
    if (/^winton(\s*motor)?(\s*raceway)?$/i.test(str)) {
      return 'Winton Motor Raceway';
    }
    if (/^phillip\s*island(\s*grand\s*prix\s*circuit|\s*gp\s*circuit|\s*circuit)?$/i.test(str)) {
      return 'Phillip Island Grand Prix Circuit';
    }
    if (/^(sydney\s*motorsport\s*park(\s*\(smsp\))?|smsp|eastern\s*creek(\s*raceway)?)$/i.test(str)) {
      return 'Sydney Motorsport Park (SMSP)';
    }
    if (/^(mount\s*panorama(\s*\(bathurst\)|\s*circuit)?|mt\.?\s*panorama|bathurst)$/i.test(str)) {
      return 'Mount Panorama (Bathurst)';
    }
    if (/^(carco\.com\.au\s*raceway(\s*\(wanneroo\))?|barbagallo(\s*raceway)?|wanneroo(\s*raceway)?)$/i.test(str)) {
      return 'CARCO.com.au Raceway (Wanneroo)';
    }
    if (/^symmons\s*plains(\s*raceway)?$/i.test(str)) {
      return 'Symmons Plains Raceway';
    }
    if (/^morgan\s*park(\s*raceway)?$/i.test(str)) {
      return 'Morgan Park Raceway';
    }
    if (/^(wakefield\s*park(\s*\/\s*one\s*raceway|\s*raceway)?|one\s*raceway)$/i.test(str)) {
      return 'Wakefield Park / One Raceway';
    }
    if (/^mallala(\s*motorsport\s*park|\s*raceway)?$/i.test(str)) {
      return 'Mallala Motorsport Park';
    }
    if (/^baskerville(\s*raceway)?$/i.test(str)) {
      return 'Baskerville Raceway';
    }
    if (/^(queensland\s*raceway(\s*\(willowbank\))?|willowbank)$/i.test(str)) {
      return 'Queensland Raceway (Willowbank)';
    }
    if (/^the\s*bend(\s*motorsport\s*park)?$/i.test(str)) {
      return 'The Bend Motorsport Park';
    }
    if (/^hidden\s*valley(\s*raceway)?$/i.test(str)) {
      return 'Hidden Valley Raceway';
    }
    return str;
  }

  function resolveSessionIsoDate(s, fallbackIso) {
    const fallback = (typeof fallbackIso === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(fallbackIso.trim()))
      ? fallbackIso.trim()
      : getLocalTodayIso();
    if (!s || typeof s !== 'object') return fallback;

    const candidates = [s.sessionIsoDate, s.sessionDateIso, s.sessionDate, s.date];
    for (const raw of candidates) {
      if (!raw || typeof raw !== 'string') continue;
      const str = raw.trim();
      if (/^\d{4}-\d{2}-\d{2}$/.test(str)) {
        return str;
      }
      // Match "11 Nov 2026" or "2 Nov 2025"
      const dmyText = str.match(/^(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})$/);
      if (dmyText) {
        const dd = String(Number(dmyText[1])).padStart(2, '0');
        const mShort = dmyText[2].slice(0, 3).toLowerCase();
        const mIdx = MONTHS_SHORT.findIndex((m) => m.toLowerCase() === mShort);
        if (mIdx !== -1) {
          const mm = String(mIdx + 1).padStart(2, '0');
          return `${dmyText[3]}-${mm}-${dd}`;
        }
      }
      // Match "DD/MM/YYYY"
      const dmySlash = str.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
      if (dmySlash) {
        const dd = String(Number(dmySlash[1])).padStart(2, '0');
        const mm = String(Number(dmySlash[2])).padStart(2, '0');
        return `${dmySlash[3]}-${mm}-${dd}`;
      }
    }
    return fallback;
  }

  function extractSessionYear(s) {
    const iso = resolveSessionIsoDate(s);
    const mIso = iso.match(/^(\d{4})-/);
    if (mIso) return mIso[1];
    const disp = String((s && (s.sessionDate || s.date)) || '');
    const mYear = disp.match(/\b(20\d{2}|19\d{2})\b/);
    return mYear ? mYear[1] : String(new Date().getFullYear());
  }

  function normalizeOptionalAfr(val) {
    if (val === null || val === undefined || val === '') return null;
    const num = Number(val);
    return Number.isFinite(num) && num > 0 ? Number(num.toFixed(2)) : null;
  }

  function normalizeOptionalWaterTemp(val) {
    if (val === null || val === undefined || val === '') return null;
    const num = Number(val);
    return Number.isFinite(num) && num > 0 ? Math.round(num) : null;
  }

